class Router:
    def __init__(self): self.routes = []
    def add(self, path, handler): self.routes.append((path, handler))
    def resolve(self, path):
        for route, handler in self.routes:
            if ':' not in route and route == path: return handler
        for route, handler in self.routes:
            left, right = route.strip('/').split('/'), path.strip('/').split('/')
            if len(left) == len(right) and all(a == b or a.startswith(':') and bool(b) for a, b in zip(left, right)): return handler
        raise KeyError(path)
